function notice(text){$('toast').textContent=text;$('toast').classList.add('show');toastTimer=1.2;}
function reload(){if(!active||!player||player.dead||player.reload>0||player.ammo===6)return;player.reload=1.15;updateHud();}
function blocked(x,y,r){for(const p of props){if(p.type==='cactus'||p.type==='barrel'||p.type==='crate'){const dx=clamp(x,p.x-p.w/2,p.x+p.w/2)-x,dy=clamp(y,p.y-p.h/2,p.y+p.h/2)-y;if(dx*dx+dy*dy<r*r)return true;}}return false;}
function moveBody(o,vx,vy,spd,delta){let nx=clamp(o.x+vx*spd*delta,35,world.w-35),ny=clamp(o.y+vy*spd*delta,35,world.h-35);if(!blocked(nx,o.y,o.r))o.x=nx;if(!blocked(o.x,ny,o.r))o.y=ny;}
function lineBlocked(x1,y1,x2,y2){const n=Math.ceil(Math.hypot(x2-x1,y2-y1)/14);for(let i=2;i<n;i++){let t=i/n,x=x1+(x2-x1)*t,y=y1+(y2-y1)*t;for(const p of props){if(Math.abs(x-p.x)<p.w*.43&&Math.abs(y-p.y)<p.h*.43)return true;}}return false;}
function puff(x,y,color,n=8,power=100){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.65),max:.65,color,size:rand(2,5)});}}
function fire(){if(!active||player.dead||player.reload>0||player.fireCd>0)return;if(knifing){knife();return;}if(player.ammo<=0){notice('EMPTY CYLINDER');hintTimer=2;return;}player.ammo--;player.fireCd=.32;shots++;shake=7;updateHud();const a=player.angle,ox=player.x+Math.cos(a)*24,oy=player.y+Math.sin(a)*24;let target=null,best=700;for(const b of bots){const dx=b.x-ox,dy=b.y-oy,d=Math.hypot(dx,dy),ba=Math.atan2(dy,dx),delta=Math.atan2(Math.sin(ba-a),Math.cos(ba-a));if(Math.abs(delta)<.12&&d<best&&!lineBlocked(ox,oy,b.x,b.y)){best=d;target=b;}}bullets.push({x:ox,y:oy,tx:target?target.x:ox+Math.cos(a)*640,ty:target?target.y:oy+Math.sin(a)*640,life:.12,player:true});puff(ox,oy,'#ffc56c',5,80);if(target){target.dead=true;score+=100;wins++;puff(target.x,target.y,'#d96f58',15,125);notice('CLEAN SHOT');}else{puff(ox+Math.cos(a)*best,oy+Math.sin(a)*best,'#c7b28a',3,45);}if(player.ammo===0)hintTimer=2;}
function knife(){if(!active||player.dead||player.knifeCd>0)return;player.knifeCd=.48;knifing=true;setTimeout(()=>{knifing=false;updateHud();},230);const target=bots.filter(b=>!b.dead&&dist(player,b)<80).sort((a,b)=>dist(player,a)-dist(player,b))[0];if(target){const da=Math.atan2(target.y-player.y,target.x-player.x),diff=Math.atan2(Math.sin(da-player.angle),Math.cos(da-player.angle));if(Math.abs(diff)<1.2){target.dead=true;wins++;score+=80;puff(target.x,target.y,'#d96f58',13,115);notice('KNIFE WORK');}}updateHud();}
function update(delta){if(!active)return;const d=Math.min(delta,.04);if(player.dead)return;player.fireCd=Math.max(0,player.fireCd-d);player.knifeCd=Math.max(0,player.knifeCd-d);if(player.reload>0){player.reload-=d;if(player.reload<=0){player.ammo=6;player.reload=0;updateHud();notice('CYLINDER LOADED');}}if(toastTimer>0){toastTimer-=d;if(toastTimer<=0)$('toast').classList.remove('show');}if(hintTimer>0){hintTimer-=d;$('hint').classList.add('show');}else $('hint').classList.remove('show');
let ix=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),iy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(touchMove.active){ix=touchMove.x;iy=touchMove.y;}const mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag;}moveBody(player,ix,iy,235,d);
const sx=player.x-camera.x,sy=player.y-camera.y;if(mouse.active)player.angle=Math.atan2(mouse.y-sy,mouse.x-sx);
if(mouse.down)fire();
for(const b of bots){if(b.dead)continue;b.fireCd-=d;b.think-=d;b.flash=Math.max(0,b.flash-d);const dx=player.x-b.x,dy=player.y-b.y,dd=Math.hypot(dx,dy)||1;b.angle=Math.atan2(dy,dx);if(b.think<=0){b.think=rand(.65,1.35);b.strafe=Math.random()<.5?-1:1;}let vx=0,vy=0;if(dd>275){vx=dx/dd;vy=dy/dd;}else if(dd<190){vx=-dx/dd;vy=-dy/dd;}else{vx=-dy/dd*b.strafe*.42;vy=dx/dd*b.strafe*.42;}moveBody(b,vx,vy,rand(74,94),d);if(b.fireCd<=0&&dd<590&&!lineBlocked(b.x,b.y,player.x,player.y)){b.fireCd=rand(1.05,1.8);bullets.push({x:b.x+Math.cos(b.angle)*22,y:b.y+Math.sin(b.angle)*22,tx:player.x+rand(-18,18),ty:player.y+rand(-18,18),life:.28,player:false});b.flash=.1;}}
bots=bots.filter(b=>!b.dead);for(const q of bullets)q.life-=d;bullets=bullets.filter(q=>q.life>0);for(const p of particles){p.life-=d;p.x+=p.vx*d;p.y+=p.vy*d;p.vx*=.93;p.vy*=.93;}particles=particles.filter(p=>p.life>0);
if(bots.length===0){round++;updateHud();showEnd(true);return;}for(const b of bots){if(dist(player,b)<20&&Math.random()<d*.42){player.dead=true;updateHud();puff(player.x,player.y,'#e2634e',14,100);showEnd(false);break;}}
const maxX=Math.max(0,world.w-W),maxY=Math.max(0,world.h-H);camera.x=clamp(player.x-W/2,0,maxX);camera.y=clamp(player.y-H/2,0,maxY);shake=Math.max(0,shake-d*25);
}
function frame(now){if(!active)return;const delta=(now-last)/1000;last=now;update(delta);draw();if(active)requestAnimationFrame(frame);}
</script>

