function frame(now){if(!active)return;const delta=(now-last)/1000;last=now;update(delta);draw();if(active)requestAnimationFrame(frame);}
function draw(){ctx.save();ctx.translate(-camera.x,-camera.y);ctx.fillStyle='#a79675';ctx.fillRect(camera.x,camera.y,W,H);const left=Math.floor(camera.x/64)*64,top=Math.floor(camera.y/64)*64;for(let x=left;x<camera.x+W+64;x+=64)for(let y=top;y<camera.y+H+64;y+=64){const n=((x*7+y*13)%11+11)%11;ctx.fillStyle=n<3?'#ae9a77':n<7?'#a49372':'#9e906f';ctx.globalAlpha=.35;ctx.fillRect(x+((n*19)%45),y+((n*31)%45),2+n%3,2);ctx.globalAlpha=1;}
// Dry, wheel-rutted main street and its rough edges
ctx.fillStyle='#b9a783';ctx.fillRect(0,world.h/2-145,world.w,290);ctx.fillStyle='#a28f6d';ctx.fillRect(0,world.h/2-155,world.w,10);ctx.fillRect(0,world.h/2+145,world.w,10);ctx.strokeStyle='#c8b58c';ctx.globalAlpha=.35;ctx.lineWidth=2;for(let i=0;i<world.w;i+=100){ctx.beginPath();ctx.moveTo(i,world.h/2-110);ctx.lineTo(i+70,world.h/2-110);ctx.moveTo(i+35,world.h/2+109);ctx.lineTo(i+92,world.h/2+109);ctx.stroke();}ctx.globalAlpha=1;
// Town limits
ctx.strokeStyle='#78694f';ctx.lineWidth=18;ctx.strokeRect(8,8,world.w-16,world.h-16);ctx.strokeStyle='#c1ab7f';ctx.lineWidth=2;ctx.strokeRect(21,21,world.w-42,world.h-42);
for(const p of props){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.rot);if(p.type==='crate'){ctx.fillStyle='#66513b';ctx.fillRect(-p.w/2+4,-p.h/2+6,p.w,p.h);ctx.fillStyle='#896a48';ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h);ctx.strokeStyle='#b49365';ctx.lineWidth=3;ctx.strokeRect(-p.w/2+4,-p.h/2+4,p.w-8,p.h-8);ctx.beginPath();ctx.moveTo(-p.w/2+5,-p.h/2+5);ctx.lineTo(p.w/2-5,p.h/2-5);ctx.moveTo(p.w/2-5,-p.h/2+5);ctx.lineTo(-p.w/2+5,p.h/2-5);ctx.stroke();}else if(p.type==='barrel'){ctx.fillStyle='#604c36';ctx.fillRect(-p.w/2+3,-p.h/2+5,p.w,p.h);ctx.fillStyle='#88734f';ctx.beginPath();ctx.ellipse(0,0,p.w*.46,p.h*.45,0,0,7);ctx.fill();ctx.strokeStyle='#b19a6c';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,0,p.w*.46,p.h*.45,0,0,7);ctx.stroke();ctx.beginPath();ctx.moveTo(-p.w*.3,-p.h*.16);ctx.lineTo(p.w*.3,-p.h*.16);ctx.moveTo(-p.w*.3,p.h*.17);ctx.lineTo(p.w*.3,p.h*.17);ctx.stroke();}else{ctx.fillStyle='#594c35';ctx.beginPath();ctx.ellipse(0,8,p.w*.39,p.h*.4,0,0,7);ctx.fill();ctx.fillStyle='#60704c';ctx.fillRect(-5,-p.h*.5,10,p.h*.7);ctx.fillRect(-p.w*.35,-p.h*.2,p.w*.7,8);ctx.fillRect(-p.w*.28,-p.h*.4,p.w*.56,7);ctx.fillRect(-p.w*.2,-p.h*.6,p.w*.4,7);}ctx.restore();}
for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
for(const b of bots)drawDude(b,false);if(player)drawDude(player,true);
for(const q of bullets){ctx.globalAlpha=clamp(q.life*5,0,1);ctx.strokeStyle=q.player?'#ffe09a':'#ff7658';ctx.lineWidth=q.player?3:2;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q.tx,q.ty);ctx.stroke();ctx.globalAlpha=1;}
ctx.restore();if(player&&active){const cx=player.x-camera.x,cy=player.y-camera.y;const ret=$('crosshair');if(mouse.active){ret.style.left=mouse.x+'px';ret.style.top=mouse.y+'px';}else{ret.style.left=(cx+Math.cos(player.angle)*120)+'px';ret.style.top=(cy+Math.sin(player.angle)*120)+'px';}}}
function drawDude(o,isPlayer){ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.angle);ctx.fillStyle='#261f18';ctx.globalAlpha=.25;ctx.beginPath();ctx.ellipse(2,7,18,14,0,0,7);ctx.fill();ctx.globalAlpha=1;
ctx.fillStyle=isPlayer?'#3e7774':'#844d3d';ctx.beginPath();ctx.ellipse(0,1,13,16,0,0,7);ctx.fill();ctx.fillStyle=isPlayer?'#72c6b7':'#ce8260';ctx.beginPath();ctx.arc(4,-4,9,0,7);ctx.fill();ctx.fillStyle=isPlayer?'#243939':'#422e28';ctx.beginPath();ctx.ellipse(3,-11,13,5,0,0,7);ctx.fill();ctx.fillRect(-5,-13,16,3);ctx.fillStyle='#33271e';ctx.fillRect(9,-3,20,5);ctx.fillStyle='#c3a369';ctx.fillRect(25,-2,7,3);if(o.flash>0){ctx.fillStyle='#ffdd8a';ctx.beginPath();ctx.arc(32,0,rand(4,8),0,7);ctx.fill();}if(isPlayer&&knifing){ctx.strokeStyle='#f0e2bd';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(12,5);ctx.lineTo(32,5);ctx.stroke();}ctx.restore();}

